/* ---- locks: the home modes open with the story only; tests open with the story or a clear made in this version ---- */
const lockClr = (id) => !!store.get("rfc_clr_" + id);
misOpen = function (i) {
  const L = misOrder(),
    p = L.indexOf(i);
  if (p <= 1) return true;
  const id = MIS[i].id,
    ch = chapterOf(id);
  if (lockClr(id)) return true;
  if (ch >= 0 && ch <= STORY.done) return true;
  return lockClr(MIS[L[p - 1]].id);
};
modeOpen = function (key) {
  const ch = chapterOf(MODELOCK[key].ch);
  return ch < 0 || STORY.done >= ch;
};

